      "venue": "2026 IEEE International Conference on Web Services (ICWS)",
      "doi": "10.1109/ICWS72778.2026.00067",
      "source_version": "publisher_pdf",
      "identity_evidence": {
        "page": 1,
        "quote": "Promise: Predictive and Cost-Optimal Migrations for Service-Continuous Edge Intelligence in Multi-UAV Networks"
      },
      "gates": {
        "primary_full_report": {
          "status": "YES",
          "rationale": "Primary 9-page IEEE ICWS conference paper (pp. 488–496) presenting the Promise schema, LST-GNN prediction, MINLP formulation, NP-hardness proofs, PDBH algorithm, and simulation evaluation.",
          "page": 1,
          "quote": "To achieve the service-continuous edge intelligence, we propose a predictive and cost-optimal migration scheme, named Promise, through jointly optimizing across-swarm UAV migration and intra-swarm service migration."
        },
        "multi_uav_evaluated": {
          "status": "YES",
          "rationale": "Section VII-A simulates three UAV swarms deployed in a monitoring area containing 5, 10, and 15 UAVs (30 UAVs total) coordinated with a ground control station.",
          "page": 7,
          "quote": "The three swarms are arranged in an equilateral triangular topology with a side length of 100 m, where the numbers of UAVs in the three swarms are set to 5, 10, and 15, respectively."
        },
        "collaborative_inference": {
          "status": "YES",
          "rationale": "Sections II, III, and VII-A model and evaluate partitioning each ResNet-18 CIFAR-10 inference task into sequential task modules distributed across different UAVs within a swarm, with predictive and failure-recovery intra-swarm service migration and cross-swarm UAV migration.",
          "page": 7,
          "quote": "Each generated task is equally partition into two task modules, which are distributed to different UAVs within the same swarm using the Greedy allocation algorithm."
        },
        "evaluative_evidence": {
          "status": "YES",
          "rationale": "Section VII reports server-based simulation experiments comparing Promise against NPG, THR-G, LSTM-P, and DTASM under 20, 40, and 80 tasks/time-slot and random UAV failures on task success rate, migration cost, and ResNet-18 inference accuracy.",
          "page": 7,
          "quote": "Considering the cost and complexity of real-world large-scale deployment, simulation experiments are performed to evaluate the effectiveness and efficiency of the proposed Promise. The experiments are conducted on a server equipped with an Intel(R) Core(TM) i5-12600KF CPU at 3.70 GHz and 32 GB RAM"
        },
