      "source_version": "publisher_pdf",
      "identity_evidence": {
        "page": 1,
        "quote": "Orion: A Collaborative Edge Inference Framework for Large Language Models Processing Multi-Sensor Data in UAV Swarms"
      },
      "gates": {
        "primary_full_report": {
          "status": "YES",
          "rationale": "Primary 26-page peer-reviewed MDPI Drones original research article presenting the Orion framework, Algorithms 1–2, theoretical boundary analyses, and comprehensive simulation evaluations.",
          "page": 3,
          "quote": "Motivated by these gaps, we propose Orion, a novel collaborative inference framework for sensor-aware LLM deployment at the edge."
        },
        "multi_uav_evaluated": {
          "status": "YES",
          "rationale": "Section 4.1 and Table 1 (p. 15) specify that the evaluated simulation models a four-UAV swarm (3 NVIDIA Jetson AGX Orin UAV nodes and 1 NVIDIA Orin NX UAV node) interconnected via inter-UAV ad hoc links (400–1000 Mb/s), with Orion partitioning Llama-2 inference across those simulated UAV nodes.",
          "page": 15,
          "quote": "UAV node (3 units) NVIDIA Jetson AGX Orin (1.88 TFLOPS, 16 GB RAM) UAV node (1 unit) NVIDIA Orin NX (3.33 TFLOPS, 32 GB RAM)"
        },
        "collaborative_inference": {
          "status": "YES",
          "rationale": "Section 3 specifies edge-only collaborative LLM inference across UAV swarm nodes using dynamic-programming layer partitioning, adaptive sequence partitioning, and speculative first-token predictive decoding across pipeline stages.",
          "page": 1,
          "quote": "Orion incorporates three innovations: (1) optimal model partitioning via dynamic programming, (2) adaptive sequence partitioning that balances causal attention load across pipeline stages, and (3) a predictive decoding mechanism that speculatively generates the first token during idle intervals."
        },
        "evaluative_evidence": {
          "status": "YES",
          "rationale": "Section 4 evaluates Orion in a Python 3.13.5 simulation framework against five baselines across Llama-2 7B/13B/70B, varying sequence lengths and bandwidths, ablation variants, break-even predictive decoding Monte Carlo trials, and noise-injection sensitivity runs.",
          "page": 14,
          "quote": "We implemented a comprehensive simulation framework in Python 3.13.5 to evaluate Orion’s performance rigorously. Our custom simulation accurately models UAV onboard capabilities, such as compute performance and memory capacity. It also captures aerial ad hoc network characteristics, including bandwidth and latency."
        },
        "date_window": {
          "status": "YES",
          "rationale": "Page 1 explicitly records publication on 26 May 2026, within the 2021-01-01 through 2026-11-25 window.",
          "page": 1,
          "quote": "Received: 17 April 2026 Revised: 15 May 2026 Accepted: 21 May 2026 Published: 26 May 2026"
        },
        "english": {
          "status": "YES",
          "rationale": "The full 26-page journal article is written in English.",
          "page": 1,
          "quote": "Unmanned aerial vehicle (UAV) swarms generate massive multi-modal sensor data streams from onboard payloads such as RGB cameras, LiDAR, and thermal sensors. Large language models (LLMs) can interpret these data for natural language-based swarm coordination."
        }
      },
      "decision": "INCLUDE",
      "primary_reason": "All six eligibility gates are YES: primary 26-page peer-reviewed Drones article (published 26 May 2026, in English) evaluating collaborative edge LLM inference partitioned across a simulated four-UAV swarm.",
      "evaluation_modes": [
        "simulation"
      ],
      "alignment": {
        "category": "core_partitioning",
        "rationale": "Core contribution is joint layer-to-UAV pipeline partitioning (Algorithm 1) and adaptive input sequence chunk partitioning (Algorithm 2) with speculative first-token prediction across heterogeneous UAV onboard nodes.",
        "page": 6,
        "quote": "To address the aforementioned challenges, we propose Orion, an edge-only collaborative inference framework specifically optimized for UAV swarms."
      },
      "unresolved": [
        "Evaluation relies on a Python 3.13.5 simulation with theoretically derived per-layer latency coefficients (Section 3.2.1, p. 10) and simulated sensor traces rather than physical Jetson cluster execution or physical UAV flight tests (deferred to Section 5.5, p. 23).",
        "Table 1 (p. 15) labels UAV/cloud entries as 'Hardware (emulated)', while Section 3.2.1 states simulation uses theoretical FLOPs/TFLOPS derivation rather than empirical hardware profiling.",
        "No UAV node failure or link-outage recovery mechanism is evaluated (environmental perturbation in Section 4.8 models Gaussian compute/bandwidth noise only)."
      ]
    },
    {
      "id": "C02",
      "title": "Multi-Agent Meta Reinforcement Learning for Reliable and Low-Latency Distributed Inference in Resource-Constrained UAV Swarms",
      "authors": [
        "Marwan Dhuheir",
        "Aiman Erbad",
        "Bechir Hamdaoui",
        "Samir Brahim Belhaouari",
