      "year": 2025,
      "venue": "IEEE Access",
      "doi": "10.1109/ACCESS.2025.3572036",
      "source_version": "publisher_pdf",
      "identity_evidence": {
        "page": 1,
        "quote": "Multi-Agent Meta Reinforcement Learning for Reliable and Low-Latency Distributed Inference in Resource-Constrained UAV Swarms"
      },
      "gates": {
        "primary_full_report": {
          "status": "YES",
          "rationale": "Primary 15-page peer-reviewed IEEE Access research article (pp. 103045–103059) presenting a system model, MINLP formulation, LDTP iterative decomposition, multi-agent meta-RL (A3C) algorithm, complexity analysis, and simulation results.",
          "page": 1,
          "quote": "To address these issues, we formulate the problem of CNN layer distribution and UAV trajectory planning (LDTP) as an optimization problem to improve latency, reliability, and resource usage."
        },
        "multi_uav_evaluated": {
          "status": "YES",
          "rationale": "Section VI evaluates swarms of multiple UAVs over a 500 m × 500 m area, including dynamic swarm size changes (5, 8, and 6 UAVs in Fig. 7) and scaling across varying UAV counts (Fig. 8).",
          "page": 12,
          "quote": "The simulation began with five UAVs in the swarm, and notably, the MARL-meta algorithm quickly converged with higher accuracy and lower latency compared to traditional DRL algorithms."
        },
        "collaborative_inference": {
          "status": "YES",
          "rationale": "Sections III–VI partition CNN layers (5-layer LeNet and 8-layer AlexNet) across multiple UAVs in a swarm that forward intermediate layer outputs over wireless links while jointly optimizing 3D UAV positions, transmission reliability, and energy constraints.",
          "page": 4,
          "quote": "After receiving the data, each UAV processes its respective layer(s) and forwards the intermediate results to the next UAV, which continues the process until the final output is generated."
        },
        "evaluative_evidence": {
          "status": "YES",
          "rationale": "Section VI presents TensorFlow 1.13.1 / Python 3.7.16 simulation experiments comparing LDTP and MARL-Meta against MARL-AC, MARL-DQN, and MARL-SAC across bandwidths, memory tiers, dynamic UAV join/leave events, UAV counts, and grid sizes.",
          "page": 10,
          "quote": "In this section, we present the simulation results that assess the performance of our proposed solutions. We employed Windows core i7, with 4 cores, an Intel Xeon CPU running at 2.2 GHz and 16 GB RAM to run the simulation experiments."
        },
        "date_window": {
          "status": "YES",
          "rationale": "Page 1 explicitly records date of publication as 20 May 2025, within the 2021-01-01 through 2026-11-25 window.",
          "page": 1,
          "quote": "Received 11 April 2025, accepted 12 May 2025, date of publication 20 May 2025, date of current version 19 June 2025."
