      },
      "gates": {
        "primary_full_report": {
          "status": "YES",
          "rationale": "Primary 11-page peer-reviewed journal article (pp. 144–154) proposing the SwarmNS-MAC link-layer frame encapsulation model, 24-byte TLV header, three-phase collective inference algorithm, and analytical latency/traffic/quorum model.",
          "page": 1,
          "quote": "This paper proposes a link-layer model of a UAV swarm mesh network, SwarmNS-MAC, in which IEEE 802.11 frames serve as direct containers for quantized fragments of intermediate DNN activations."
        },
        "multi_uav_evaluated": {
          "status": "YES",
          "rationale": "Section 3 (p. 4) models a multi-UAV swarm graph G(t) = (V, E(t)) where UAV nodes V compute local split-DNN layers (1..k) and transmit intermediate activation tensors to an aggregator node collecting from neighbors N(i). Under Protocol Section 4.1(4) and Amendment 001, mathematical performance studies are eligible evaluation methods and neither network simulation nor executed DNNs are required; Section 6 connects that multi-UAV architecture to numerical evaluation by setting n = 6 aggregator neighbors (Table 2, p. 6) and computing binomial aggregation quorum probabilities (Eq. (7), p. 6; pp. 7–8, Fig. 3) from single-hop per-link tensor delivery (Table 3, p. 7). The single-hop and analytical assumptions disclosed on pp. 8–9 (Table 4, Section 7) are quality-appraisal and synthesis limitations rather than a failure of multi-UAV eligibility.",
          "page": 4,
          "quote": "The swarm is represented by a dynamic graph G(t) = (V, E(t)), where V is the set of UAVs, and E(t) is the set of bidirectional radio links, which changes due to mobility."
        },
        "collaborative_inference": {
          "status": "YES",
          "rationale": "Sections 3–5 formalize split DNN inference across UAV swarm nodes computing local layers 1..k, quantizing and encapsulating intermediate activation tensors into L2 frames, and executing final layers at an aggregator with quorum-based graceful degradation.",
          "page": 1,
          "quote": "In the split computing paradigm, a deep neural network (DNN) is partitioned among swarm nodes, so that instead of raw imagery the nodes exchange intermediate activation tensors"
        },
        "evaluative_evidence": {
          "status": "YES",
          "rationale": "Sections 5–6 provide an analytical mathematical performance model and numerical evaluation for a 256×80×80 YOLO-like activation tensor comparing L2 SwarmNS-MAC against L2–L7 across FP32, INT8, and 0.8-bit quantization, effective link speeds, tensor delivery probability, and quorum probability.",
          "page": 6,
          "quote": "The calculations were performed for a reference feature tensor of dimensions 256×80×80 (1,638,400 elements), typical for the intermediate layers of YOLO-family object detectors with a 640×640 input image."
        },
        "date_window": {
          "status": "UNCERTAIN",
          "rationale": "The PDF prints only the journal issue year 2026 (Vol. 6, No. 2, 2026) and a receipt date '(Received 1 September 2026)' on page 1, with no month or day of publication anywhere in the report.",
          "page": 2,
          "quote": "Information and communication technologies, electronic engineering, Vol. 6, No. 2, pp. 144–154 (2026)"
        },
        "english": {
          "status": "YES",
          "rationale": "The main body, tables, figures, limitations, conclusions, and references (pp. 1–10) are written in English; page 11 contains only a Ukrainian abstract/metadata block.",
          "page": 1,
          "quote": "The transition from single unmanned aerial vehicles (UAVs) to coordinated swarms performing collective perception missions creates a fundamental tension between the volume of sensor data that must be exchanged and the limited, unstable bandwidth of flying ad hoc networks (FANET)."
        }
      },
      "decision": "UNCERTAIN",
      "primary_reason": "Unresolved date_window gate: the supplied report provides only issue year 2026 (Vol. 6, No. 2, 2026 on p. 2; Received 1 September 2026 on p. 1) without a dated publication record before the 2026-11-25 cutoff, preventing inclusion; all other five eligibility gates are YES.",
      "evaluation_modes": [
        "analytical"
      ],
      "alignment": {
        "category": "supporting_architecture",
        "rationale": "Develops a link-layer (IEEE 802.11 MAC) frame-encapsulation specification and analytical transport/quorum model (pp. 1, 4–8) to support split DNN collective inference in UAV swarm mesh networks; simulation and DNN accuracy experiments are deferred to future work (pp. 8–9).",
        "page": 1,
        "quote": "This paper proposes a link-layer model of a UAV swarm mesh network, SwarmNS-MAC, in which IEEE 802.11 frames serve as direct containers for quantized fragments of intermediate DNN activations."
